def latestTimeByReplacingZeroes(s: str) -> str:
    res = list(s)

    # Handle HH:
    # Case for the first digit of HH (res[0])
    if res[0] == '?':
        # If the second digit is '0' or '1' or '?', we can use '1' for the first digit.
        # Because the max HH is 11.
        if res[1] == '?' or res[1] <= '1':
            res[0] = '1'
        else:
            res[0] = '0'

    # Case for the second digit of HH (res[1])
    if res[1] == '?':
        # If the first digit is '1', the max second digit is '1'.
        # If the first digit is '0', the max second digit is '9'.
        if res[0] == '1':
            res[1] = '1'
        else:
            res[1] = '9'

    # Handle MM:
    # Case for the first digit of MM (res[3])
    if res[3] == '?':
        # Max first digit for minutes is '5'.
        res[3] = '5'

    # Case for the second digit of MM (res[4])
    if res[4] == '?':
        # Max second digit for minutes is '9'.
        res[4] = '9'

    return "".join(res)
```

