import sys

def solve():
    # Read the input
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    polyominoes_raw = []
    for i in range(3):
        grid = lines[i*4 : (i+1)*4]
        polyominoes_raw.append(grid)

    def rotate(shape):
        # Rotate a list of (r, c) coordinates 90 degrees clockwise
        # (r, c) -> (c, -r)
        return [(c, -r) for r, c in shape]

    def normalize(shape):
        # Shift coordinates so the top-leftmost square is (0, 0)
        min_r = min(r for r, c in shape)
        min_c = min(c for r, c in shape)
        return sorted([(r - min_r, c - min_c) for r, c in shape])

    def get_all_rotations(raw_grid):
        # Extract coordinates of #
        shape = []
        for r in range(4):
            for c in range(4):
                if raw_grid[r][c] == '#':
                    shape.append((r, c))

        rotations = []
        current_shape = shape
        for _ in range(4):
            rotations.append(normalize(current_shape))
            current_shape = rotate(current_shape)

        # Remove duplicate rotations (e.g., for a square)
        unique_rots = []
        for rot in rotations:
            if rot not in unique_rots:
                unique_rots.append(rot)
        return unique_rots

    # Get all possible rotations for each polyomino
    all_options = [get_all_rotations(p) for p in polyominoes_raw]

    # Total cells must be 16 to fill a 4x4 grid
    total_cells = sum(len(opt[0]) for opt in all_options)
    if total_cells != 16:
        print("No")
        return

    # Try all combinations of rotations and translations
    def can_place(grid, shape, dr, dc):
        for r, c in shape:
            nr, nc = r + dr, c + dc
            if not (0 <= nr < 4 and 0 <= nc < 4) or grid[nr][nc]:
                return False
        return True

    def place(grid, shape, dr, dc, val):
        for r, c in shape:
            grid[r + dr][c + dc] = val

    def backtrack(poly_idx, grid):
        if poly_idx == 3:
            # Check if grid is completely filled
            return all(all(row) for row in grid)

        # Try every rotation of the current polyomino
        for rot in all_options[poly_idx]:
            # Try every possible translation (top-left can be anywhere from -3 to 3)
            for dr in range(-3, 4):
                for dc in range(-3, 4):
                    if can_place(grid, rot, dr, dc):
                        place(grid, rot, dr, dc, True)
                        if backtrack(poly_idx + 1, grid):
                            return True
                        place(grid, rot, dr, dc, False)
        return False

    initial_grid = [[False for _ in range(4)] for _ in range(4)]
    if backtrack(0, initial_grid):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()

```

