import sys

def solve():
    # Read all input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    M = int(input_data[1])

    # Use a large constant for infinity
    INF = float('inf')

    # Initialize distance matrix for Floyd-Warshall
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    ptr = 2
    for _ in range(M):
        u = int(input_data[ptr]) - 1
        v = int(input_data[ptr+1]) - 1
        w = int(input_data[ptr+2])
        dist[u][v] = min(dist[u][v], w)
        ptr += 3

    # Floyd-Warshall to find all-pairs shortest paths
    for k in range(N):
        for i in range(N):
            if dist[i][k] == INF: continue
            for j in range(N):
                if dist[k][j] < INF:
                    if dist[i][j] > dist[i][k] + dist[k][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

    # DP state: dp[mask][last_vertex]
    # mask: bitmask of visited vertices
    # last_vertex: the current vertex the walk ends at
    dp = [[INF] * N for _ in range(1 << N)]

    # Base case: starting at any vertex i
    for i in range(N):
        dp[1 << i][i] = 0

    # Fill DP table
    for mask in range(1, 1 << N):
        for u in range(N):
            if dp[mask][u] == INF:
                continue

            # Try moving to vertex v
            for v in range(N):
                if dist[u][v] == INF:
                    continue

                new_mask = mask | (1 << v)
                new_dist = dp[mask][u] + dist[u][v]
                if dp[new_mask][v] > new_dist:
                    dp[new_mask][v] = new_dist

    # The answer is the minimum value in dp[(1 << N) - 1][i] for all i
    ans = INF
    final_mask = (1 << N) - 1
    for i in range(N):
        ans = min(ans, dp[final_mask][i])

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    solve()
```

```python
def smallestString(s: str) -> str:
    n = len(s)
    s_list = list(s)

    # Find the first character that is not 'a'
    start = -1
    for i in range(n):
        if s_list[i] != 'a':
            start = i
            break

    # If the string consists only of 'a's, we must still perform one operation.
    # To keep it lexicographically smallest, we change the last character 'a' to 'z'.
    if start == -1:
        s_list[-1] = 'z'
        return "".join(s_list)

    # From the first non-'a' character, continue replacing characters
    # until we hit another 'a' or the end of the string.
    for i in range(start, n):
        if s_list[i] == 'a':
            break
        # Shift character back: 'b' -> 'a', ..., 'z' -> 'y'
        # ord('a') is 97. (ord(char) - 97 - 1) % 26 + 97 converts a->z, b->a, etc.
        s_list[i] = chr((ord(s_list[i]) - ord('a') - 1) % 26 + ord('a'))

    return "".join(s_list)
```

