import sys

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = [list(row) for row in input_data[2:]]

    # exists[i][j] is True if the cookie at (i, j) is still there
    exists = [[True for _ in range(W)] for _ in range(H)]

    # Row and Column counts to optimize checking
    # row_counts[i][char] = number of cookies of color 'char' in row i
    row_counts = [{} for _ in range(H)]
    col_counts = [{} for _ in range(W)]

    for r in range(H):
        for c in range(W):
            char = grid[r][c]
            row_counts[r][char] = row_counts[r].get(char, 0) + 1
            col_counts[c][char] = col_counts[c].get(char, 0) + 1

    # Track remaining cookies in each row/column
    row_remaining = [W] * H
    col_remaining = [H] * W

    while True:
        marked = [[False for _ in range(W)] for _ in range(H)]
        any_marked = False

        # Check rows
        for r in range(H):
            if row_remaining[r] >= 2:
                # If all remaining cookies in row r have the same color
                # There is only one key in the counts dictionary that equals row_remaining
                for char, count in row_counts[r].items():
                    if count == row_remaining[r]:
                        for c in range(W):
                            if exists[r][c] and grid[r][c] == char:
                                marked[r][c] = True
                                any_marked = True
                        break

        # Check columns
        for c in range(W):
            if col_remaining[c] >= 2:
                for char, count in col_counts[c].items():
                    if count == col_remaining[c]:
                        for r in range(H):
                            if exists[r][c] and grid[r][c] == char:
                                marked[r][c] = True
                                any_marked = True
                        break

        if not any_marked:
            break

        # Remove marked cookies and update counts
        for r in range(H):
            for c in range(W):
                if marked[r][c]:
                    exists[r][c] = False
                    char = grid[r][c]
                    row_counts[r][char] -= 1
                    col_counts[c][char] -= 1
                    row_remaining[r] -= 1
                    col_remaining[c] -= 1

    # Count remaining
    ans = sum(row_remaining)
    print(ans)

if __name__ == "__main__":
    solve()
```

