def minLength(s: str) -> int:
    stack = []
    for char in s:
        if stack:
            # Check if the last character in the stack and the current character 
            # form one of the removable patterns "AB" or "CD"
            if (stack[-1] == 'A' and char == 'B') or (stack[-1] == 'C' and char == 'D'):
                stack.pop()
                continue
        stack.append(char)
    return len(stack)
