```python
def furthest_point(moves: str) -> int:
    """
    Calculates the maximum distance from the origin after n moves.
    'L' forces left (-1), 'R' forces right (+1), and '_' can be either.
    To maximize distance, we try to move as far left as possible and as far right as possible,
    then take the maximum absolute value of those two scenarios.
    """
    # To get furthest right: 'R' -> +1, 'L' -> -1, '_' -> +1
    right_pos = 0
    for char in moves:
        if char == 'R' or char == '_':
            right_pos += 1
        else:
            right_pos -= 1

    # To get furthest left: 'L' -> -1, 'R' -> +1, '_' -> -1
    left_pos = 0
    for char in moves:
        if char == 'L' or char == '_':
            left_pos -= 1
        else:
            left_pos += 1

    return max(abs(right_pos), abs(left_pos))
```

```python
def solve(s, k):
    n = len(s)

    def get_changes(sub):
        m = len(sub)
        if m < 2:
            return float('inf')

        min_total_changes = float('inf')
        # Find all divisors d such that 1 <= d < m and m % d == 0
        for d in range(1, m):
            if m % d == 0:
                current_d_changes = 0
                # For each group based on modulo d
                for i in range(d):
                    # The sequence is sub[i], sub[i+d], sub[i+2d]...
                    # This sequence must be a palindrome
                    group = [sub[j] for j in range(i, m, d)]
                    l, r = 0, len(group) - 1
                    while l < r:
                        if group[l] != group[r]:
                            current_d_changes += 1
                        l += 1
                        r -= 1
                min_total_changes = min(min_total_changes, current_d_changes)
        return min_total_changes

    # Precompute costs for all possible substrings [i, j)
    cost = [[float('inf')] * (n + 1) for _ in range(n)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            cost[i][j] = get_changes(s[i:j])

    # DP: dp[i][j] is the min cost to partition s[0:j] into i substrings
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(1, k + 1):
        # j must be at least 2*i because each semi-palindrome needs length >= 2
        for j in range(2 * i, n + 1):
            # Try all possible split points p
            # The last substring is s[p:j], which must have length >= 2
            for p in range(2 * (i - 1), j - 1):
                if dp[i-1][p] != float('inf') and cost[p][j] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i-1][p] + cost[p][j])

    return dp[k][n]
```

