def countBeautifulSubstrings(s: str, k: int) -> int:
    vowels_set = set('aeiou')
    n = len(s)
    count = 0

    # Iterate through all possible starting positions of the substring
    for i in range(n):
        vowels = 0
        consonants = 0
        # Extend the substring from the starting position i
        for j in range(i, n):
            if s[j] in vowels_set:
                vowels += 1
            else:
                consonants += 1

            # A string is beautiful if:
            # 1. vowels == consonants
            # 2. (vowels * consonants) % k == 0
            if vowels == consonants:
                if (vowels * consonants) % k == 0:
