def longestCommonSuffix(wordsContainer, wordsQuery):
    # A Trie stores prefixes. Since we need suffixes, we insert strings reversed.
    # Each node in the Trie will store the index of the "best" string 
    # passing through that node.
    # "Best" is defined as: smallest length, then smallest index.
    trie = {}

    for i, word in enumerate(wordsContainer):
        # Reverse the word to treat suffix as prefix
        rev_word = word[::-1]
        node = trie
        # Update root for cases where there is no common suffix (empty suffix)
        if 'best_idx' not in node:
            node['best_idx'] = i
        else:
            curr_best = node['best_idx']
            if len(word) < len(wordsContainer[curr_best]):
                node['best_idx'] = i
            # If lengths are equal, the smaller index (i) is already handled 
            # by the fact that we iterate i from 0 upwards and only update on '<'.

        for char in rev_word:
            if char not in node:
                node[char] = {}
            node = node[char]

            if 'best_idx' not in node:
                node['best_idx'] = i
            else:
                curr_best = node['best_idx']
                if len(word) < len(wordsContainer[curr_best]):
                    node['best_idx'] = i

    ans = []
    for query in wordsQuery:
        rev_query = query[::-1]
        node = trie
        best_found_idx = trie['best_idx']

        for char in rev_query:
            if char in node:
                node = node[char]
                best_found_idx = node['best_idx']
            else:
                break
        ans.append(best_found_idx)

    return ans
