import sys

def solve():
    # Use fast I/O
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    T_prime = input_data[1]
    len_tp = len(T_prime)

    results = []

    # The input consists of N strings starting from index 2
    for i in range(N):
        S = input_data[i + 2]
        len_s = len(S)

        # The condition is that the Edit Distance between T and T' is at most 1.
        # This is a restricted case of edit distance.

        # Case 1: Lengths differ by more than 1, cannot be transformed by 1 operation
        if abs(len_s - len_tp) > 1:
            continue

        possible = False

        if len_s == len_tp:
            # T' equals T OR T' obtained by changing one character in T
            diff_count = 0
            for j in range(len_s):
                if S[j] != T_prime[j]:
                    diff_count += 1
                    if diff_count > 1:
                        break
            if diff_count <= 1:
                possible = True

        elif len_s == len_tp - 1:
            # T' obtained by inserting one character into T (S)
            # Check if S is a subsequence of T_prime with only one char difference
            # effectively: can we delete one char from T_prime to get S?
            it_s = 0
            it_tp = 0
            diffs = 0
            while it_s < len_s and it_tp < len_tp:
                if S[it_s] == T_prime[it_tp]:
                    it_s += 1
                    it_tp += 1
                else:
                    it_tp += 1
                    diffs += 1
                    if diffs > 1:
                        break
            if diffs <= 1:
                # Account for remaining char at end of T_prime
                if diffs + (len_tp - it_tp) <= 1:
                    possible = True

        elif len_s == len_tp + 1:
            # T' obtained by deleting one character from T (S)
            # effectively: can we delete one char from S to get T_prime?
            it_s = 0
            it_tp = 0
            diffs = 0
            while it_s < len_s and it_tp < len_tp:
                if S[it_s] == T_prime[it_tp]:
                    it_s += 1
                    it_tp += 1
                else:
                    it_s += 1
                    diffs += 1
                    if diffs > 1:
                        break
            if diffs <= 1:
                # Account for remaining char at end of S
                if diffs + (len_s - it_s) <= 1:
                    possible = True

        if possible:
            results.append(i + 1)

    # Output result
    print(len(results))
    print(*(results))

if __name__ == "__main__":
    solve()

