def min_t_length(s: str) -> int:
    n = len(s)
    # The length of t must be a divisor of the length of s.
    # We want the minimum length, so we check divisors in increasing order.
    for length in range(1, n + 1):
        if n % length == 0:
            # Extract the first block to use as the reference anagram (t)
            # We only need the character counts of the first block.
            t_counts = {}
            for i in range(length):
                char = s[i]
                t_counts[char] = t_counts.get(char, 0) + 1

            possible = True
            # Check every subsequent block of the same length
            for start in range(length, n, length):
                current_counts = {}
                for i in range(start, start + length):
                    char = s[i]
                    current_counts[char] = current_counts.get(char, 0) + 1

                if current_counts != t_counts:
                    possible = False
                    break

            if possible:
                return length
    return n
