import sys
from itertools import permutations

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])

    A = []
    idx = 2
    for i in range(H):
        A.append([int(x) for x in input_data[idx : idx + W]])
        idx += W

    B = []
    for i in range(H):
        B.append([int(x) for x in input_data[idx : idx + W]])
        idx += W

    # Function to calculate the number of swaps (inversions) to reach a permutation
    def count_swaps(p):
        swaps = 0
        p = list(p)
        for i in range(len(p)):
            # Find where the value i is currently located
            for j in range(i, len(p)):
                if p[j] == i:
                    # Bubble it up to position i
                    for k in range(j, i, -1):
                        p[k], p[k-1] = p[k-1], p[k]
                        swaps += 1
                    break
        return swaps

    min_ops = float('inf')
    found = False

    # Since H, W <= 5, we can iterate over all permutations of rows and columns
    # Row permutations
    for row_p in permutations(range(H)):
        # Col permutations
        for col_p in permutations(range(W)):
            # Check if grid A transformed by row_p and col_p matches grid B
            # A[row_p[i]][col_p[j]] should be B[i][j]
            match = True
            for i in range(H):
                for j in range(W):
                    if A[row_p[i]][col_p[j]] != B[i][j]:
                        match = False
                        break
                if not match:
                    break

            if match:
                found = True
                # The total operations is the number of adjacent swaps to get 
                # the identity sequence [0, 1, ..., N-1] to [row_p] and [col_p]
                # This is equivalent to the number of inversions in the permutation.
                ops = count_swaps(row_p) + count_swaps(col_p)
                if ops < min_ops:
                    min_ops = ops

    if not found:
        print("-1")
    else:
        print(min_ops)

if __name__ == "__main__":
    solve()
