def countIncremovableSubarrays(nums):
    n = len(nums)
    count = 0

    # A subarray is defined by its start index i and end index j (inclusive)
    for i in range(n):
        for j in range(i, n):
            # Create a new list by removing the subarray from index i to j
            # The remaining elements are from 0 to i-1 and j+1 to n-1
            remaining = nums[:i] + nums[j+1:]

            # Check if the remaining list is strictly increasing
            is_increasing = True
            for k in range(len(remaining) - 1):
                if remaining[k] >= remaining[k+1]:
                    is_increasing = False
                    break

            if is_increasing:
                count += 1

    return count
