import sys

# Increase recursion depth for deep DFS in grids
sys.setrecursionlimit(2000000)

def solve():
    # Read H and W from the first line of input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = input_data[2:]

    visited = [[False for _ in range(W)] for _ in range(H)]

    def get_neighbors(r, c):
        # 8-connectivity: horizontal, vertical, and diagonal
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < H and 0 <= nc < W:
                    yield nr, nc

    # Iterative DFS to avoid RecursionError on very large connected components
    def dfs(start_r, start_c):
        stack = [(start_r, start_c)]
        visited[start_r][start_c] = True
        while stack:
            r, c = stack.pop()
            for nr, nc in get_neighbors(r, c):
                if grid[nr][nc] == '#' and not visited[nr][nc]:
                    visited[nr][nc] = True
                    stack.append((nr, nc))

    component_count = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '#' and not visited[r][c]:
                component_count += 1
                dfs(r, c)

    print(component_count)

if __name__ == "__main__":
