def minimumOperations(nums, k):
    nums.sort()
    n = len(nums)
    # The median is the middle element (larger of two if even length)
    # Index for the median in a 0-indexed sorted array of size n is n // 2
    mid_idx = n // 2

    ops = 0
    # If the current median is less than k, we need to increase the median 
    # and potentially elements to its right to maintain sorted property.
    if nums[mid_idx] < k:
        for i in range(mid_idx, n):
            if nums[i] < k:
                ops += k - nums[i]
            else:
                # Since the array is sorted, once we hit an element >= k, 
                # all subsequent elements are also >= k.
                break
    # If the current median is greater than k, we need to decrease the median
    # and potentially elements to its left.
    elif nums[mid_idx] > k:
        for i in range(mid_idx, -1, -1):
            if nums[i] > k:
                ops += nums[i] - k
            else:
                # Since the array is sorted, once we hit an element <= k,
                # all previous elements are also <= k.
                break

    return ops
```

