def solve(nums, moveFrom, moveTo):
    # Use a set to keep track of occupied positions for O(1) updates and lookups
    occupied = set(nums)

    # Process each movement step
    for from_pos, to_pos in zip(moveFrom, moveTo):
        # If there are marbles at the from_pos, move them to to_pos
        if from_pos in occupied:
            occupied.remove(from_pos)
            occupied.add(to_pos)

    # Return the sorted list of unique occupied positions
    return sorted(list(occupied))
