def punishmentNumber(n: int) -> int:
    def can_partition(s: str, target: int) -> bool:
        # Base case: if string is empty, check if target is reached
        if not s:
            return target == 0

        # Optimization: target cannot be negative
        if target < 0:
            return False

        # Try all possible split points for the first contiguous substring
        for i in range(1, len(s) + 1):
            substring = s[:i]
            val = int(substring)
            # Recursively check if the remainder of the string can sum to (target - val)
            if can_partition(s[i:], target - val):
                return True

        return False

    total_punishment = 0
    for i in range(1, n + 1):
        square_val = i * i
        if can_partition(str(square_val), i):
            total_punishment += square_val

    return total_punishment
