import heapq

def minimumCost(source: str, target: str, original: list[str], changed: list[str], cost: list[int]) -> int:
    # We have 26 lowercase English letters.
    # Use Floyd-Warshall or Dijkstra to find the shortest path between any two characters.
    # Since the number of nodes is small (26), Dijkstra from each node is efficient.

    adj = [[] for _ in range(26)]
    for u, v, w in zip(original, changed, cost):
        adj[ord(u) - ord('a')].append((ord(v) - ord('a'), w))

    # dist[i][j] will be the minimum cost to convert character i to character j
    dist = [[float('inf')] * 26 for _ in range(26)]

    for start_node in range(26):
        dist[start_node][start_node] = 0
        pq = [(0, start_node)]
        while pq:
            d, u = heapq.heappop(pq)
            if d > dist[start_node][u]:
                continue
            for v, weight in adj[u]:
                if dist[start_node][u] + weight < dist[start_node][v]:
                    dist[start_node][v] = dist[start_node][u] + weight
                    heapq.heappush(pq, (dist[start_node][v], v))

    total_cost = 0
    for s, t in zip(source, target):
        if s == t:
            continue
        u, v = ord(s) - ord('a'), ord(t) - ord('a')
        if dist[u][v] == float('inf'):
            return -1
        total_cost += dist[u][v]

    return total_cost
