def maxAlternatingSubarray(nums):
    max_len = -1
    n = len(nums)

    for i in range(n - 1):
        # Check if a potential alternating subarray starts here
        if nums[i+1] - nums[i] == 1:
            current_len = 2
            # Extend the subarray as far as possible
            for j in range(i + 2, n):
                # The required difference alternates between -1 and 1
                # For index j, the difference (nums[j] - nums[j-1]) should be 1 if (j-i) is odd, -1 if even
                expected_diff = 1 if (j - i) % 2 != 0 else -1
                if nums[j] - nums[j-1] == expected_diff:
                    current_len += 1
                else:
                    break
            max_len = max(max_len, current_len)

    return max_len
