def smallestBeautifulString(s: str, k: int) -> str:
    n = len(s)
    min_len = float('inf')
    result = ""

    # Sliding window or brute force since n is small (up to 100)
    for i in range(n):
        ones_count = 0
        for j in range(i, n):
            if s[j] == '1':
                ones_count += 1

            if ones_count == k:
                current_substring = s[i : j + 1]
                current_len = len(current_substring)

                if current_len < min_len:
                    min_len = current_len
                    result = current_substring
                elif current_len == min_len:
                    if current_substring < result:
                        result = current_substring
                # Since we are looking for the shortest, once we hit k ones, 
                # extending j further will only increase length.
                break
            elif ones_count > k:
                break

    return result
