def getSmallestString(s: str, k: int) -> str:
    def get_dist(c1, c2):
        # Calculate cyclic distance between two lowercase characters
        d = abs(ord(c1) - ord(c2))
        return min(d, 26 - d)

    res = list(s)
    n = len(s)

    for i in range(n):
        # Try changing the current character to the smallest possible letter ('a' to 'z')
        for char_code in range(ord('a'), ord('z') + 1):
            target_char = chr(char_code)
            cost = get_dist(s[i], target_char)

            if cost <= k:
                # Check if this change is feasible.
                # Since we want the lexicographically smallest string, 
                # we take the first char_code that satisfies the remaining k.
                res[i] = target_char
                k -= cost
                break

    return "".join(res)
