def minimumSum(nums):
    n = len(nums)
    min_sum = float('inf')
    found = False

    # Since the constraints are very small (n <= 50), 
    # a triple loop O(n^3) is efficient enough.
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # Check mountain condition: i < j < k and nums[i] < nums[j] and nums[k] < nums[j]
                if nums[i] < nums[j] and nums[k] < nums[j]:
                    current_sum = nums[i] + nums[j] + nums[k]
                    if current_sum < min_sum:
                        min_sum = current_sum
                        found = True

    return min_sum if found else -1
